const $=id=>document.getElementById(id), key='framecraft-project-v1';
const newScene=()=>({id:crypto.randomUUID(),name:'',type:'Opening / title card',duration:8,text:'',description:'',background:'#789378',imagePrompt:'',imageEdit:'',motion:'Slow zoom in',transition:'Fade',clipPrompt:'',revisionPrompt:'',outputContainer:'MP4',outputResolution:'1080p',outputFps:'30',voiceText:'',voiceStyle:'Warm & conversational',voicePrompt:'',music:'No music',musicPrompt:'',soundEffects:'',volume:25,assets:[]});
const defaults=()=>({version:1,title:'',format:'Landscape · 16:9',language:'English',audience:'',style:'Cinematic',captions:true,thumbnail:true,metadata:true,chapters:false,scenes:[newScene()]});
let project;try{project=JSON.parse(localStorage.getItem(key))||defaults()}catch{project=defaults()}
project.scenes=project.scenes.map(s=>({...newScene(),...s}));
let active=0,urls=new Map(),db;
const request=indexedDB.open('framecraft-assets',1);request.onupgradeneeded=()=>request.result.createObjectStore('assets');request.onsuccess=()=>{db=request.result;hydrate()};request.onerror=()=>toast('Asset storage is unavailable. Keep your original files.');
function assetOp(mode,fn){return new Promise((resolve,reject)=>{if(!db)return reject(Error('Asset storage is not ready'));const tx=db.transaction('assets',mode);let r=fn(tx.objectStore('assets'));r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function hydrate(){for(const s of project.scenes)for(const a of s.assets){try{const blob=await assetOp('readonly',st=>st.get(a.id));if(blob)urls.set(a.id,URL.createObjectURL(blob))}catch{}}preview()}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(s){$('toast').textContent=s;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',3500)}
function save(){try{localStorage.setItem(key,JSON.stringify(project))}catch{toast('Unable to save this project. Export JSON to keep your work.')}}
const field=(name,label,placeholder='')=>`<label>${label}<input data-field="${name}" value="${esc(project.scenes[active][name])}" placeholder="${esc(placeholder)}"></label>`;
const area=(name,label,placeholder='')=>`<label>${label}<textarea data-field="${name}" placeholder="${esc(placeholder)}">${esc(project.scenes[active][name])}</textarea></label>`;
const select=(name,label,options)=>`<label>${label}<select data-field="${name}">${options.map(o=>`<option ${project.scenes[active][name]===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`;
function upload(kind,label,accept){const s=project.scenes[active];return `<label>${label}</label><div class="upload"><strong>＋ Choose ${kind==='image'?'images':['video','revision'].includes(kind)?'video clips':'audio files'}</strong><p>Keep your original files for the AI production tool.</p><input aria-label="${label}" type="file" data-upload="${kind}" accept="${accept}" multiple></div>${s.assets.filter(a=>a.kind===kind).map(a=>`<div class="asset"><span>${a.kind==='revision'?'Revision '+(a.revision||1)+' · ':''}${esc(a.name)} · ${(a.size/1024/1024).toFixed(1)} MB</span>${a.kind==='revision'&&urls.has(a.id)?`<video controls preload="metadata" src="${urls.get(a.id)}" style="width:100%;max-height:220px;margin-top:10px"></video>`:''}<button data-remove="${a.id}" aria-label="Remove ${esc(a.name)}">×</button></div>`).join('')}`}
function tabs(){$('count').textContent=project.scenes.length;$('scenes').innerHTML=project.scenes.map((s,i)=>`<button class="scene-tab ${i===active?'active':''}" data-scene="${i}">${String(i+1).padStart(2,'0')} &nbsp; ${esc(s.name||(['Opening','Main content','Closing'][i]||'Scene '+(i+1)))}</button>`).join('')}
function render(){tabs();const s=project.scenes[active];$('editor').innerHTML=`<div class="editor-top"><h3>Scene ${String(active+1).padStart(2,'0')} <span style="color:#a1aba1;font-weight:400">/ ${esc(s.type)}</span></h3><div class="tools"><button data-action="up" aria-label="Move scene earlier">↑</button><button data-action="down" aria-label="Move scene later">↓</button><button data-action="copy">Duplicate</button><button data-action="delete" aria-label="Delete scene">×</button></div></div><div class="grid two">${field('name','Scene name','Give this scene a name')}${select('type','Scene type',['Opening / title card','Text / explanation','Video / footage','Closing / call to action'])}</div><div class="grid two">${field('text','On-screen text','Your opening headline') }<label>Duration (seconds)<input data-field="duration" type="number" min="1" max="3600" value="${s.duration}"></label></div>${area('description','Content & direction','Describe what happens in this scene and the message to communicate.')}<div class="block-title"><span>▧</span> Visuals & background</div><div class="grid two"><label>Background color<input type="color" data-field="background" value="${esc(s.background)}"></label>${select('motion','Image movement',['Static','Slow zoom in','Slow zoom out','Pan left','Pan right','Crossfade slideshow'])}</div>${upload('image','Reference images','image/*')}<div style="margin-top:18px">${area('imagePrompt','Or describe an image to generate','e.g. A quiet Japanese street at sunrise, cinematic light')}</div><div style="margin-top:14px">${area('imageEdit','How should the images change?','e.g. Remove the background, warm the colors, add a title, keep the subject consistent')}</div><div class="block-title"><span>▷</span> Video clips</div>${upload('video','Upload source footage','video/*')}<div class="block-title"><span>↻</span> AI clip revisions</div><p class="caption">Upload a clip returned by your AI tool, review it, and describe the next changes. Each upload is kept as a revision.</p>${upload('revision','Reload AI-generated or modified clips','video/*')}<div style="margin-top:16px">${area('revisionPrompt','Next revision instructions','e.g. Keep the subject and timing; remove flicker and soften the lighting.')}</div><div class="grid two" style="margin-top:16px">${select('outputContainer','Requested video format',['MP4','WebM','MOV'])}${select('outputResolution','Requested resolution',['720p','1080p','1440p','2160p (4K)'])}</div>${select('outputFps','Frame rate',['24','25','30','50','60'])}<div style="margin-top:18px">${area('clipPrompt','Clip descriptions & editing instructions','Describe generated clips, trims, order, speed, or overlays.')}</div><div style="margin-top:14px">${select('transition','Transition to next scene',['Fade','Cut','Dissolve','Slide','None'])}</div><div class="block-title"><span>♫</span> Voice & audio</div>${area('voiceText','Narration script','What should the voice say?')}<div class="grid two" style="margin-top:16px">${select('voiceStyle','Voice style',['Warm & conversational','Energetic','Calm & reassuring','Professional','Dramatic','No voiceover'])}${field('voicePrompt','Voice direction','e.g. Gentle pace, natural pauses')}</div><div class="grid two">${select('music','Background music',['No music','Ambient','Acoustic','Lo-fi','Cinematic','Upbeat','Custom / uploaded'])}<label>Music volume: <span id="volume-label">${s.volume}%</span><input data-field="volume" type="range" min="0" max="100" value="${s.volume}"></label></div>${field('musicPrompt','Music description','Mood, tempo, instrumentation, or uploaded track name')}<div style="margin-top:14px">${field('soundEffects','Sound effects','e.g. Soft wind, birds, transition whoosh')}</div><div style="margin-top:18px">${upload('audio','Music, voice or sound effects','audio/*')}</div>`;preview()}
function preview(){const s=project.scenes[active];if(!s)return;const a=s.assets.find(a=>a.kind==='image'&&urls.has(a.id));$('preview').style.backgroundColor=s.background;$('preview').style.backgroundImage=a?`url("${urls.get(a.id)}")`:'none';$('preview').style.aspectRatio=project.format.includes('9:16')?'9/16':project.format.includes('1:1')?'1':'16/9';$('preview-text').textContent=s.text||'Your story starts here';$('preview-number').textContent=`SCENE ${String(active+1).padStart(2,'0')} · ${s.duration}s`;$('summary').innerHTML=`<div>◷ &nbsp; ${project.scenes.reduce((n,s)=>n+Number(s.duration),0)}s total runtime</div><div>▧ &nbsp; ${esc(project.format)}</div><div>◎ &nbsp; ${esc(project.language)} · ${esc(s.voiceStyle)}</div><div>♫ &nbsp; ${esc(s.music)}</div>`}
function syncSettings(){for(const id of ['title','format','language','audience','style','captions','thumbnail','metadata','chapters']){const el=$(id);if(el.type==='checkbox')el.checked=project[id];else el.value=project[id];el.oninput=()=>{project[id]=el.type==='checkbox'?el.checked:el.value;save();preview()}}}
$('scenes').onclick=e=>{const b=e.target.closest('[data-scene]');if(b){active=Number(b.dataset.scene);render()}};
$('editor').oninput=e=>{const k=e.target.dataset.field;if(!k)return;project.scenes[active][k]=['duration','volume'].includes(k)?Math.min(k==='duration'?3600:100,Math.max(k==='duration'?1:0,Number(e.target.value)||1)):e.target.value;if(k==='volume')$('volume-label').textContent=e.target.value+'%';save();tabs();preview()};
$('editor').onchange=async e=>{const kind=e.target.dataset.upload;if(!kind)return;const s=project.scenes[active];for(const file of e.target.files){if(!file.type.startsWith(kind==='image'?'image/':['video','revision'].includes(kind)?'video/':'audio/')){toast('Choose a supported '+kind+' file');continue}const id=crypto.randomUUID();try{await assetOp('readwrite',st=>st.put(file,id));s.assets.push({id,name:file.name,size:file.size,mime:file.type,kind,revision:kind==='revision'?Math.max(0,...s.assets.filter(a=>a.kind==='revision').map(a=>a.revision||0))+1:undefined});urls.set(id,URL.createObjectURL(file))}catch{toast('Unable to store this file. Browser storage may be full.')}}save();render()};
$('editor').onclick=async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.remove){const id=b.dataset.remove;project.scenes[active].assets=project.scenes[active].assets.filter(a=>a.id!==id);if(!project.scenes.some(s=>s.assets.some(a=>a.id===id))){try{await assetOp('readwrite',st=>st.delete(id))}catch{}URL.revokeObjectURL(urls.get(id));urls.delete(id)}}const action=b.dataset.action;if(action==='copy'){const copy=structuredClone(project.scenes[active]);copy.id=crypto.randomUUID();copy.name=(copy.name||'Scene')+' copy';project.scenes.splice(active+1,0,copy);active++}if(action==='delete'){if(project.scenes.length===1)return toast('Keep at least one scene.');project.scenes.splice(active,1);active=Math.min(active,project.scenes.length-1)}if(action==='up'&&active>0){[project.scenes[active-1],project.scenes[active]]=[project.scenes[active],project.scenes[active-1]];active--}if(action==='down'&&active<project.scenes.length-1){[project.scenes[active+1],project.scenes[active]]=[project.scenes[active],project.scenes[active+1]];active++}save();render()};
$('add').onclick=()=>{const s=newScene();s.type='Video / footage';project.scenes.push(s);active=project.scenes.length-1;save();render()};
function brief(){const p=project;return `# ${p.title||'Untitled video'} — AI production brief\n\nCreate a YouTube video from the following plan. Generate the requested materials; report any unsupported capability or missing asset. Do not invent uploaded assets.\n\n## Project\n- Format: ${p.format}\n- Language: ${p.language}\n- Visual style: ${p.style}\n- Audience and purpose: ${p.audience||'Not specified'}\n- Total planned runtime: ${p.scenes.reduce((n,s)=>n+Number(s.duration),0)} seconds\n\n## Asset handoff\nUploaded files are referenced by filename below, not embedded in this brief. Supply the original files alongside this document. Project JSON contains editable settings and file references, not media.\n\n${p.scenes.map((s,i)=>`## Scene ${i+1}: ${s.name||s.type}\n- Type: ${s.type}\n- Duration: ${s.duration}s\n- On-screen text: ${s.text||'None'}\n- Content direction: ${s.description||'Not specified'}\n- Background: ${s.background}\n- Image generation prompt: ${s.imagePrompt||'None'}\n- Image edit instructions: ${s.imageEdit||'None'}\n- Image movement: ${s.motion}\n- Video generation / editing: ${s.clipPrompt||'None'}\n- AI revision instructions: ${s.revisionPrompt||'None'}\n- Requested clip output: ${s.outputContainer}, ${s.outputResolution}, ${s.outputFps} fps\n- Revision input: ${s.assets.filter(a=>a.kind==='revision').sort((a,b)=>(b.revision||0)-(a.revision||0))[0]?.name||'None; use source footage'} (use latest revision as the input; preserve earlier versions)\n- Transition: ${s.transition}\n- Narration (${p.language}): ${s.voiceText||'None'}\n- Voice style: ${s.voiceStyle}\n- Voice direction: ${s.voicePrompt||'None'}\n- Music: ${s.music}\n- Music direction: ${s.musicPrompt||'None'}\n- Music volume: ${s.volume}% (duck beneath narration)\n- Sound effects: ${s.soundEffects||'None'}\n- Source files: ${s.assets.map(a=>`${a.name} (${a.kind}${a.revision?' #'+a.revision:''}, ${a.mime}, ${a.size} bytes)`).join('; ')||'None'}\n`).join('\n')}\n## Deliverables\n- Final edited video in the selected aspect ratio, with a scene-by-scene asset and edit list.\n${p.captions?'- Subtitles in the selected language as SRT and optionally burned-in captions.\n':''}${p.thumbnail?'- Three thumbnail concepts and AI image prompts; 1280×720 for standard YouTube thumbnails.\n':''}${p.metadata?'- Suggested YouTube title, description, tags, and upload checklist.\n':''}${p.chapters?'- Timestamped YouTube chapters based on final scene timings.\n':''}- Use music and footage cleared for the intended use. List source attribution requirements.\n- Review spelling, narration timing, safe text placement, audio balance, and export quality before delivery.\n`}
function download(){if(!project.title.trim()){toast('Add a video title before exporting.');$('title').focus();return}const fmt=$('export-format').value;const payload=fmt==='json'?JSON.stringify({...project,exportedAt:new Date().toISOString(),assetHandoff:'Supply original media files separately; this file includes references only.'},null,2):brief();const blob=new Blob([payload],{type:fmt==='json'?'application/json':'text/markdown'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(project.title.replace(/[^a-z0-9_-]/gi,'-').slice(0,70)||'video')+'-production.'+fmt;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Production file downloaded. Supply original media files alongside it.')}
$('export').onclick=download;$('download').onclick=download;
$('import').onclick=()=>$('import-file').click();$('import-file').onchange=async e=>{try{const p=JSON.parse(await e.target.files[0].text());if(p.version!==1||!Array.isArray(p.scenes)||!p.scenes.length||p.scenes.length>500)throw Error();const sample=newScene();if(p.scenes.some(s=>!s||typeof s!=='object'||(s.assets&&!Array.isArray(s.assets))))throw Error();project={...defaults(),...p,scenes:p.scenes.map(s=>({...sample,...s,id:typeof s.id==='string'?s.id:crypto.randomUUID(),duration:Math.min(3600,Math.max(1,Number(s.duration)||8)),background:/^#[a-f0-9]{6}$/i.test(s.background)?s.background:sample.background,assets:(s.assets||[]).filter(a=>a&&typeof a.name==='string'&&typeof a.id==='string')}))};active=0;save();syncSettings();render();hydrate();toast('Project imported. Media references need their original files.')}catch{toast('This file is not a valid Framecraft project JSON.')}e.target.value=''};
$('reset').onclick=()=>{if(!confirm('Start a new project? Export JSON first if you want to keep the current plan.'))return;project=defaults();active=0;save();syncSettings();render()};
syncSettings();render();
